using System.IO;
namespace MRS;
internal static class LcnSurveyTests
{
 internal static void Run(Action<bool,string> check)
 {
  var now=DateTimeOffset.UtcNow;const long control=451600000,voice=461800000,other=451925000;
  DmrObservation Grant(uint tg=91,uint? radio=123)=>new(6,3,1,radio,tg,true,true,"","CRC valid"){SystemType="DMR Tier III",Network=5,Site=1,GrantChannel=3,GrantSlot=2,Detail="Tier III group voice grant"};
  DmrObservation Voice(uint tg=91,uint? radio=123)=>new(6,1,2,radio,tg,true,true,"","Full LC valid"){SystemType="DMR Tier III"};
  DmrReception R(DmrObservation f,long hz,DateTimeOffset time,bool replay=false)=>new(f,new("synthetic","Synthetic survey",replay,hz),time);
  LcnSurvey New(){var m=new LcnSurvey();m.Configure("DMR:DMR Tier III:Network 5:Site 1",control,[control,voice,other]);m.Data.WaitForEnd=false;m.Start(now);m.Applied(control,now);return m;}
  void Return(LcnSurvey m,DateTimeOffset t){m.Tick(t);if(m.AppliedHz==0)m.Applied(m.DesiredHz,t);}
  var m=New();check(m.Phase=="Reacquiring"&&m.Rows().Length==0,"Survey waits for validated control evidence rather than treating tune acknowledgement as control lock");
  m.Observe(R(Grant() with{LinkValid=false},control,now));m.Observe(R(Grant(),control,now,true));m.Observe(R(Grant() with{Network=9},control,now));check(m.Phase=="Reacquiring","Invalid, replay and foreign-site assignments never start a probe");
  m.Observe(R(Grant(),control,now));check(m.Phase=="Tuning probe"&&m.AppliedHz==0&&m.DesiredHz==other,"One unresolved assignment schedules exactly one candidate and waits for acknowledgement");
  m.Observe(R(Voice(),other,now));check(m.Data.Evidence.Count==0,"Buffered observations cannot match a pending unacknowledged tune");
  m.Applied(other,now.AddSeconds(1));m.Observe(R(Voice() with{Slot=1},other,now.AddSeconds(1.1)));m.Observe(R(Voice() with{LinkValid=false},other,now.AddSeconds(1.2)));check(m.Data.Evidence.Count==0,"Wrong-slot and failed-validation voice never counts as evidence");
  m.Observe(R(Voice(92),other,now.AddSeconds(1.3)));check(m.Rows().Single().Calls==0&&m.Rows().Single().Status=="Inconclusive","An active but unrelated candidate is not a successful mapping or a site-wide search block");
  Return(m,now.AddSeconds(6));m.Observe(R(Grant(),control,now.AddSeconds(7)));check(m.DesiredHz==voice,"After an inconclusive attempt the next assignment tests the next saved candidate");m.Applied(voice,now.AddSeconds(7.3));m.Observe(R(Voice(),voice,now.AddSeconds(7.5)));m.Observe(R(Voice(),voice,now.AddSeconds(8)));check(m.Rows().Single(r=>r.Hz==voice).Calls==1,"Repeated full LC packets from one conversation count as one call");
  m.Tick(now.AddSeconds(10));check(m.Phase=="Returning"&&m.DesiredHz==control,"Discovery returns after a bounded identity window even when matching headers keep arriving");m.Applied(control,now.AddSeconds(10.3));m.Observe(R(Grant(),control,now.AddSeconds(11)));check(m.Rows().Single(r=>r.Hz==voice).Calls==1,"Elapsed time and repeated assignment alone cannot inflate separate-call evidence");
  m=New();
  for(int i=0;i<3;i++){
   var t=now.AddSeconds(i*10);m.Observe(R(Grant(),control,t));long candidate=m.DesiredHz;m.Applied(candidate,t.AddSeconds(.3));m.Observe(R(Voice(),candidate,t.AddSeconds(.5)));m.Observe(R(Voice() with{DataType=2},candidate,t.AddSeconds(1)));check(m.Phase=="Returning","Matching terminator ends the probe and provides an independent-call boundary");m.Applied(control,t.AddSeconds(1.3));
  }
  long passed=m.Rows().Single(r=>r.Status=="Passed").Hz;check(m.Rows().Single(r=>r.Status=="Passed").Calls==3&&m.Summary.Contains("total inventory unknown"),"Three separate calls pass a unique mapping without claiming the entire site inventory is known");
  m.Observe(R(Grant() with{GrantChannel=4},control,now.AddSeconds(35)));check(m.Summary.Contains("incomplete")&&m.Rows().Any(r=>r.Lcn==4&&r.Hz==0),"New unresolved channel numbers immediately make the site map incomplete");
  m.Stop();string root=Path.Combine(Path.GetTempPath(),"mrs-survey-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string file=Path.Combine(root,"research.json");m.Save(file);var loaded=new LcnSurvey();loaded.Load(file);check(!loaded.Running&&loaded.Passed(3)&&loaded.Data.Calls.Count==m.Data.Calls.Count,"Restart retains evidence and call identities, but never starts radio discovery automatically");loaded.Start(now.AddMinutes(1));check(loaded.DesiredHz==control&&loaded.Rows().Any(r=>r.Hz==passed),"Resume returns to control and retains discovered mappings");
  string original=File.ReadAllText(file);File.WriteAllText(file,"{broken");bool failed=false;try{loaded.Load(file);}catch{failed=true;}check(failed&&File.ReadAllText(file)=="{broken"&&loaded.Passed(3),"Malformed research is not overwritten or allowed to replace the working map");File.WriteAllText(file,original);
  var conflict=loaded.Data.Evidence.First(e=>e.Lcn==3);loaded.Data.Evidence.Add(conflict with{Hz=conflict.Hz==voice?other:voice,Call="independent-competing-call"});check(!loaded.Passed(3)&&loaded.Rows().Where(r=>r.Lcn==3).All(r=>r.Status.StartsWith("Conflict")),"A competing frequency association removes passed status rather than choosing the first to three");loaded.Stop();loaded.Reject(3,conflict.Hz==voice?other:voice);check(loaded.Passed(3),"Explicit review can reject a competing association without erasing its evidence");
  var malformed=System.Text.Json.Nodes.JsonNode.Parse(original)!;malformed["Protocol"]=null;File.WriteAllText(file,malformed.ToJsonString());failed=false;try{loaded.Load(file);}catch(IOException){failed=true;}check(failed&&loaded.Passed(3),"Structurally invalid research fields cannot reach the running state machine or replace valid evidence");File.WriteAllText(file,original);
  long rejectedHz=conflict.Hz==voice?other:voice;loaded.Data.Frequencies=loaded.Data.Frequencies.Where(h=>h!=rejectedHz).ToArray();check(loaded.Rows().Where(r=>r.Lcn==3&&r.Hz==rejectedHz).All(r=>r.Status.StartsWith("Rejected")),"Excluding a rejected frequency cannot revive its rejected mapping label");
  var follow=New();follow.Data.Follow=true;follow.Data.TryTentative=true;follow.Observe(R(Grant(),control,now));follow.Applied(follow.DesiredHz,now.AddSeconds(.3));follow.Observe(R(Voice(),follow.AppliedHz,now.AddSeconds(.5)));check(follow.Phase=="Following","Optional follow-and-learn follows a validated tentative identity only when explicitly enabled");follow.Tick(now.AddSeconds(22));check(follow.Phase=="Returning","Follow and learn returns on its maximum dwell when a terminator is missed");
  var recovery=New();recovery.Tick(now.AddSeconds(6));check(recovery.Phase=="Searching control/rest"&&recovery.DesiredHz!=control,"Loss of control starts bounded saved-frequency reacquisition");recovery.Applied(recovery.DesiredHz,now.AddSeconds(6.5));recovery.Observe(R(Voice(),recovery.AppliedHz,now.AddSeconds(7)));check(recovery.Phase=="Reacquiring","Ordinary traffic does not falsely lock the control search");
  var foreign=Grant() with{SystemType="Connect Plus",Detail="Control-channel identity",Network=99};recovery.Observe(R(foreign,recovery.AppliedHz,now.AddSeconds(7.5)));check(recovery.Phase=="Reacquiring","Foreign network control signaling is rejected during reacquisition");
  check(LcnSurvey.Role(Grant())=="Control — decoded"&&LcnSurvey.Role(Grant() with{SystemType="Connect Plus",Detail="Traffic-channel identity"})=="Voice — observed","Decoded control and traffic channel roles remain distinct");
  var rest=Grant() with{SystemType="Capacity Plus",Detail="Capacity Plus channel status · fragment 3",RestChannel=4};check(LcnSurvey.Role(rest).StartsWith("Rest")&&LcnSurvey.Role(rest with{DataType=1,Detail="Capacity Plus full link control"})=="","A voice LC announcing a rest number does not prove its own frequency is rest");
  var roles=SiteChannelData.FromDmr(R(Grant(),control,now));check(roles?.Role=="Control — decoded","DMR discovery saves decoded channel roles instead of discarding them as observed carrier");
  var db=new FrequencyLibrary(Path.Combine(root,"frequencies.json"));db.SaveSiteChannels([roles!]);var channel=db.Items.Single(i=>!i.IsFolder);check(channel.Name.Contains("Control"),"Generated saved and spectrum labels include the decoded control role");
  var restChannel=SiteChannelData.FromDmr(R(rest with { ColorCode=1, Network=null, Site=null },463562500,now))!;
  db.SaveSiteChannels([restChannel]);
  var restSaved=db.Items.Single(i=>i.FrequencyHz==restChannel.Hz);
  check(restSaved.Name=="Cap+ · CC 1 · Rest"&&restSaved.Signaling.Contains("CC 1"),
   "New Capacity Plus rest entries show the decoded color code in the saved label");
  var legacyRest=restSaved with { Name="Rest — last observed" };
  check(legacyRest.ToString().StartsWith("Cap+ · CC 1 · Rest"),
   "An existing role-only Cap+ entry renders its saved color code before any new save");
  db.Upsert(legacyRest);
  db.SaveSiteChannels([restChannel with { Seen=now.AddSeconds(1) }]);
  check(db.Items.Single(i=>i.FrequencyHz==restChannel.Hz) is { Name:"Cap+ · CC 1 · Rest" } refreshed&&
        refreshed.Id==restSaved.Id,
   "A fresh Capacity Plus decode fixes the legacy label in place");
  var a=New();var b=New();a.Observe(R(Grant(),control,now));check(a.Phase=="Tuning probe"&&b.Phase=="Reacquiring"&&b.Data.Evidence.Count==0,"Independent receiver surveys do not share active assignments or search state");
  var timeout=New();timeout.Observe(R(Grant(),control,now));timeout.Tick(now.AddSeconds(7));check(!timeout.Running&&timeout.Message.Contains("acknowledgement"),"Failed tune acknowledgement stops discovery without a fabricated match");
  var cc=New();cc.Observe(R(Grant(),control,now));cc.Applied(cc.DesiredHz,now.AddSeconds(.3));cc.Observe(R(Voice() with{ColorCode=7},cc.AppliedHz,now.AddSeconds(.5)));check(cc.Rows().All(r=>r.Calls==0),"A same-talkgroup voice on a different color code cannot pass a mapping");
  var followConflict=New();followConflict.Data.Follow=followConflict.Data.TryTentative=true;followConflict.Observe(R(Grant(),control,now));followConflict.Applied(followConflict.DesiredHz,now.AddSeconds(.3));long followHz=followConflict.AppliedHz;followConflict.Observe(R(Voice(),followHz,now.AddSeconds(.5)));followConflict.Observe(R(Voice(92),followHz,now.AddSeconds(1)));check(followConflict.Phase=="Returning"&&!followConflict.Passed(3),"Contradictory full LC revokes following immediately and holds the mapping for review");
  var unknownRadio=New();unknownRadio.Observe(R(Grant(radio:null),control,now));unknownRadio.Applied(unknownRadio.DesiredHz,now.AddSeconds(.2));unknownRadio.Observe(R(Voice(),unknownRadio.AppliedHz,now.AddSeconds(.5)));Return(unknownRadio,now.AddSeconds(3));unknownRadio.Observe(R(Grant(),control,now.AddSeconds(4)));check(unknownRadio.Rows().Sum(r=>r.Calls)==1,"Learning a previously missing radio ID does not manufacture another independent call");
  var capSurvey=new LcnSurvey();capSurvey.Configure("DMR:Capacity Plus:Unassigned:Site 1",control,[control,voice]);capSurvey.Data.WaitForEnd=false;capSurvey.Start(now);capSurvey.Applied(control,now);
  DmrObservation Cap(bool busy){var p=new byte[12];p[0]=0xBE;p[1]=0x10;p[2]=0xC1;if(busy){p[3]=0x20;p[4]=91;}int crc=TrunkSignaling.Crc16(p.AsSpan(0,10))^0xA5A5;p[10]=(byte)(crc>>8);p[11]=(byte)crc;return TrunkSignaling.Enrich(new(6,3,1,null,null,false,false,"",""),p);}
  for(int i=0;i<3;i++){var t=now.AddSeconds(i*10);capSurvey.Observe(R(Cap(true),control,t));check(capSurvey.Phase=="Tuning probe"&&capSurvey.Rows().Any(r=>r.Lcn==2),"CRC-valid Cap+ LSN 3 becomes carrier LCN 2 with slot 1");capSurvey.Applied(voice,t.AddSeconds(.3));capSurvey.Observe(R(Voice() with{SystemType="Capacity Plus",Slot=1},voice,t.AddSeconds(.5)));Return(capSurvey,t.AddSeconds(3));capSurvey.Observe(R(Cap(false),control,t.AddSeconds(4)));}
  check(capSurvey.Passed(2),"Complete Cap+ idle snapshots establish three separate call boundaries without invented elapsed-time boundaries");
  var con=New();con.Data.Scope="DMR:Connect Plus:Network 5:Site 1";con.Observe(R(Grant() with{SystemType="Connect Plus",Detail="Control-channel identity",GrantChannel=null,GrantSlot=null,Group=false},control,now));con.Observe(R(DmrFollowingTests.ConGrant with{Network=5,Site=1},control,now.AddSeconds(.1)));check(con.Phase=="Tuning probe"&&con.Data.Protocol=="Connect Plus","Connect Plus decoded control identity and validated grants drive the same single-receiver workflow");
  var waitEnd=New();waitEnd.Data.WaitForEnd=true;waitEnd.Observe(R(Grant(),control,now));waitEnd.Applied(waitEnd.DesiredHz,now.AddSeconds(.3));waitEnd.Observe(R(Voice(),waitEnd.AppliedHz,now.AddSeconds(.5)));waitEnd.Tick(now.AddSeconds(4));check(waitEnd.Phase=="Probe","Accuracy mode waits for a call-ending boundary instead of immediately abandoning a matched call");waitEnd.Tick(now.AddSeconds(22));check(waitEnd.Phase=="Returning","Call-end waiting has a bounded maximum and never blocks discovery indefinitely");
  var oldIds=new FrequencyItem{Name="Custom label",Notes="Preserve notes",FrequencyHz=voice,SiteScope=m.Data.Scope,ChannelIds="LCN 3"};db.Upsert(oldIds);db.UpdateSurveyEntries([oldIds with{ChannelRoles="Voice — observed"}]);check(db.Items.Single(i=>i.Id==oldIds.Id).Notes=="Preserve notes","Atomic research metadata updates preserve existing labels and notes");db.Undo();check(db.Items.Single(i=>i.Id==oldIds.Id).ChannelRoles=="","One Undo restores the entire research metadata batch");
  Task.Run(async()=>{
   using var radio=new LcnSurveyRadio();radio.Tune(control);var samples=TrunkTests.DmrSamples(TrunkTests.CapStatus,true);const int rate=240000;double phase=0;var bytes=new byte[samples.Length*5*2];for(int i=0;i<bytes.Length/2;i++){phase+=2*Math.PI*samples[i/5]/rate;bytes[2*i]=(byte)Math.Clamp((int)Math.Round(127.5+90*Math.Cos(phase)),0,255);bytes[2*i+1]=(byte)Math.Clamp((int)Math.Round(127.5+90*Math.Sin(phase)),0,255);}
   for(int i=0;i<bytes.Length;i+=8192)radio.Feed(new(0,control,rate,bytes.Skip(i).Take(8192).ToArray(),rate));var decoded=new List<DmrReception>();for(int i=0;i<300&&!decoded.Any(r=>r.Fields.LinkValid&&r.Fields.SystemType=="Capacity Plus");i++){await Task.Delay(10);decoded.AddRange(radio.Drain());}check(decoded.Any(r=>r.Fields.LinkValid&&r.Fields.SystemType=="Capacity Plus")&&radio.Error.Length==0,"Generated DMR RF passes the production raw-I/Q survey downconverter and decoder");
   radio.Tune(0);check(radio.Drain().Length==0&&radio.DrainAudio().Length==0,"A tune-generation boundary discards queued old-frequency decoder observations and audio");radio.Tune(control);radio.Feed(new(0,control,rate,new byte[100],rate,IqSampleFormat.Signed16LittleEndian));check(radio.Error.Length>0,"Unsupported research I/Q is an explicit failure rather than usable evidence");
  }).GetAwaiter().GetResult();
 }
}
